SET NAMES utf8mb4;
SELECT 'competition_entries' check_item,COUNT(*) value FROM beer_entry WHERE competition_id=1070 AND deleted_flag=0;
SELECT 'competition_labels' check_item,COUNT(*) value FROM entry_scan_label WHERE competition_id=1070 AND status='ACTIVE';
SELECT 'target_entries' check_item,COUNT(DISTINCT entry.id) value FROM beer_entry entry JOIN entry_scan_label label ON label.beer_entry_id=entry.id WHERE entry.competition_id=1070 AND entry.deleted_flag=0 AND label.short_code IN ('54531','54532','54533','54534','62884','55190','81451');
SELECT 'short_code_duplicates' check_item,COUNT(*) value FROM (SELECT short_code FROM entry_scan_label WHERE competition_id=1070 GROUP BY short_code HAVING COUNT(*)>1) duplicated;
SELECT 'scan_token_duplicates' check_item,COUNT(*) value FROM (SELECT scan_token FROM entry_scan_label WHERE competition_id=1070 GROUP BY scan_token HAVING COUNT(*)>1) duplicated;
SELECT 'invalid_target_labels' check_item,COUNT(*) value FROM entry_scan_label WHERE competition_id=1070 AND short_code IN ('54531','54532','54533','54534','62884','55190','81451') AND (status<>'ACTIVE' OR CHAR_LENGTH(short_code)<>5 OR short_code NOT REGEXP '^[0-9]{5}$' OR CHAR_LENGTH(scan_token)<>64 OR scan_token NOT REGEXP '^Q[0-9A-F]{63}$');
SELECT 'target_extra_field_missing' check_item,COUNT(*) value FROM (SELECT entry.id FROM beer_entry entry JOIN entry_scan_label label ON label.beer_entry_id=entry.id LEFT JOIN beer_entry_extra_field extra ON extra.beer_entry_id=entry.id AND extra.field_key IN ('specialIngredients','custom_1785549677921_0089y') WHERE entry.competition_id=1070 AND entry.deleted_flag=0 AND label.short_code IN ('54531','54532','54533','54534','62884','55190','81451') GROUP BY entry.id HAVING COUNT(DISTINCT extra.field_key)<>2) missing;
SELECT 'target_extra_field_mismatch' check_item,COUNT(*) value FROM beer_entry entry JOIN entry_scan_label label ON label.beer_entry_id=entry.id JOIN beer_entry_extra_field extra ON extra.beer_entry_id=entry.id WHERE entry.competition_id=1070 AND entry.deleted_flag=0 AND label.short_code IN ('54531','54532','54533','54534','62884','55190','81451') AND extra.field_key IN ('specialIngredients','custom_1785549677921_0089y') AND extra.field_value<>JSON_UNQUOTE(JSON_EXTRACT(entry.extra_fields_json,CONCAT('$.',extra.field_key)));
SELECT 'target_style_link_missing' check_item,COUNT(*) value FROM beer_entry entry JOIN entry_scan_label label ON label.beer_entry_id=entry.id LEFT JOIN competition_style_config style ON style.id=entry.style_config_id AND style.competition_id=entry.competition_id WHERE entry.competition_id=1070 AND entry.deleted_flag=0 AND label.short_code IN ('54531','54532','54533','54534','62884','55190','81451') AND (style.id IS NULL OR style.active_flag<>1 OR style.name<>entry.style);
SELECT 'target_account_missing' check_item,COUNT(*) value FROM beer_entry entry JOIN entry_scan_label label ON label.beer_entry_id=entry.id LEFT JOIN portal_account account ON account.brewery_id=entry.brewery_id AND account.status=1 WHERE entry.competition_id=1070 AND entry.deleted_flag=0 AND label.short_code IN ('54531','54532','54533','54534','62884','55190','81451') AND account.id IS NULL;
SELECT 'target_account_multiplicity' check_item,COUNT(*) value FROM (SELECT entry.id FROM beer_entry entry JOIN entry_scan_label label ON label.beer_entry_id=entry.id LEFT JOIN portal_account account ON account.brewery_id=entry.brewery_id AND account.status=1 WHERE entry.competition_id=1070 AND entry.deleted_flag=0 AND label.short_code IN ('54531','54532','54533','54534','62884','55190','81451') GROUP BY entry.id HAVING COUNT(account.id)<>1) invalid;
SELECT 'target_chinese_question_marks' check_item,COUNT(*) value FROM beer_entry entry JOIN brewery brewery ON brewery.id=entry.brewery_id JOIN entry_scan_label label ON label.beer_entry_id=entry.id WHERE entry.competition_id=1070 AND entry.deleted_flag=0 AND label.short_code IN ('54531','54532','54533','54534','62884','55190','81451') AND (entry.name LIKE '%???%' OR entry.style LIKE '%???%' OR brewery.company_name LIKE '%???%' OR entry.extra_fields_json LIKE '%???%');
SELECT 'imported_styles' check_item,COUNT(*) value FROM competition_style_config WHERE competition_id=1070 AND source_library_version='REGISTRATION_FORM_20260808_20260811' AND active_flag=1;
SELECT 'category_1593_targets' check_item,COUNT(*) value FROM beer_entry entry JOIN entry_scan_label label ON label.beer_entry_id=entry.id WHERE entry.competition_id=1070 AND entry.deleted_flag=0 AND entry.category_id=1593 AND label.short_code IN ('54531','54532','54533','54534','62884','55190','81451');
SELECT 'category_1594_targets' check_item,COUNT(*) value FROM beer_entry entry JOIN entry_scan_label label ON label.beer_entry_id=entry.id WHERE entry.competition_id=1070 AND entry.deleted_flag=0 AND entry.category_id=1594 AND label.short_code IN ('54531','54532','54533','54534','62884','55190','81451');
SELECT label.short_code,entry.name,brewery.company_name,brewery.contact_name,CONCAT('***',RIGHT(account.phone,4)) account_phone,entry.category_id,entry.style,entry.abv,JSON_UNQUOTE(JSON_EXTRACT(entry.extra_fields_json,'$.specialIngredients')) special_ingredients,JSON_UNQUOTE(JSON_EXTRACT(entry.extra_fields_json,'$.custom_1785549677921_0089y')) promotion,CHAR_LENGTH(label.scan_token) token_length,label.status FROM beer_entry entry JOIN brewery brewery ON brewery.id=entry.brewery_id JOIN entry_scan_label label ON label.beer_entry_id=entry.id LEFT JOIN portal_account account ON account.brewery_id=brewery.id AND account.status=1 WHERE entry.competition_id=1070 AND entry.deleted_flag=0 AND label.short_code IN ('54531','54532','54533','54534','62884','55190','81451') ORDER BY label.short_code,account.id;
SELECT CONCAT('***',RIGHT(account.phone,4)) account_phone,brewery.company_name,brewery.contact_name,brewery.wechat,account.wechat,COUNT(DISTINCT CASE WHEN label.id IS NOT NULL THEN entry.id END) target_entries FROM portal_account account JOIN brewery brewery ON brewery.id=account.brewery_id LEFT JOIN beer_entry entry ON entry.brewery_id=brewery.id AND entry.competition_id=1070 AND entry.deleted_flag=0 LEFT JOIN entry_scan_label label ON label.beer_entry_id=entry.id AND label.short_code IN ('54531','54532','54533','54534','62884','55190','81451') WHERE account.phone IN ('15954545181','18208851300','13706205156') GROUP BY account.phone,brewery.company_name,brewery.contact_name,brewery.wechat,account.wechat ORDER BY account.phone;
SELECT field_key,required_flag,visible_to_judges,active_flag FROM entry_field_config WHERE competition_id=1070 AND field_key IN ('specialIngredients','custom_1785549677921_0089y') ORDER BY sort_order;
